from collections import defaultdict

class LockManager:
    def __init__(self):
        self.adj = defaultdict(set)

    def add_dependency(self, waiter: int, holder: int):
        if waiter != holder:
            self.adj[waiter].add(holder)
            if holder not in self.adj:
                self.adj[holder] = set()
        else:
            self.adj[waiter].add(holder)

    def remove_dependency(self, waiter: int, holder: int):
        if waiter in self.adj and holder in self.adj[waiter]:
            self.adj[waiter].remove(holder)

    def _dfs_cycle(self, node: int, visited: dict, path: list, cycle_result: list) -> bool:
        visited[node] = 1
        path.append(node)
        for neighbor in sorted(self.adj[node]):
            if visited.get(neighbor, 0) == 1:
                cycle_start_idx = path.index(neighbor)
                cycle_result.extend(path[cycle_start_idx:] + [neighbor])
                return True
            elif visited.get(neighbor, 0) == 0:
                if self._dfs_cycle(neighbor, visited, path, cycle_result):
                    return True
        visited[node] = 2
        path.pop()
        return False

    def find_deadlock_cycle(self) -> list[int] | None:
        visited = {}
        for node in sorted(self.adj.keys()):
            if visited.get(node, 0) == 0:
                cycle = []
                if self._dfs_cycle(node, visited, [], cycle):
                    return cycle
        return None

    def has_deadlock(self) -> bool:
        return self.find_deadlock_cycle() is not None

    def resolve_deadlock(self, policy: str = 'youngest') -> int | None:
        cycle = self.find_deadlock_cycle()
        if not cycle:
            return None
        cycle_nodes = set(cycle[:-1])
        if policy == 'youngest':
            victim = max(cycle_nodes)
        else:
            victim = min(cycle_nodes)
        if victim in self.adj:
            del self.adj[victim]
        for u in list(self.adj.keys()):
            self.adj[u].discard(victim)
        return victim
